level_2_cta_topologies.cuda_hip_example:
WP_KERNEL_SCOPE(0u);
// accumulator zero-init...
WP_B(3u, 0u);
for (int kt = 0; kt < num_k_tiles; ++kt) {
    // global -> shared load + __syncthreads() + wmma/mfma...
}
WP_E(3u, 0u);
WP_B(6u, 0u);
// epilogue shared/global C writeback nest...
WP_E(6u, 0u);

const int wg_id = threadIdx.x / 128;
WP_KERNEL_SCOPE(wg_id == 0 ? 1u : 0u);
if (wg_id == 0) {
    WP_B(1u, 0u);
    for (int kt = 0; kt < num_k_tiles; ++kt) { /* mbarrier wait + async load + arrive */ }
    WP_E(1u, 0u);
} else {
    WP_B(3u, 0u);
    for (int kt = 0; kt < num_k_tiles; ++kt) { /* mbarrier wait + mma + arrive */ }
    WP_E(3u, 0u);
    WP_B(6u, 0u);
    /* epilogue store to C */
    WP_E(6u, 0u);
}
